import{U as e,W as t,nt as n,t as r}from"./chunks/framework.CPHJXLir.js";var i=JSON.parse(`{"title":"Page Objects","description":"","frontmatter":{},"headers":[],"relativePath":"pages-and-user-interfaces/page-objects.md","filePath":"pages-and-user-interfaces/page-objects.md"}`),a={name:`pages-and-user-interfaces/page-objects.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="page-objects" tabindex="-1">Page Objects <a class="header-anchor" href="#page-objects" aria-label="Permalink to “Page Objects”">​</a></h1><h2 id="what-is-a-page-object" tabindex="-1">What is a Page Object? <a class="header-anchor" href="#what-is-a-page-object" aria-label="Permalink to “What is a Page Object?”">​</a></h2><p>A Page Object in AL defines the user interface through which users interact with Business Central data and functionality.</p><p>Think of it this way:</p><ul><li>Table objects define how data is stored.</li><li>Page objects define how users interact with that data.</li><li>Codeunits contain reusable business logic.</li></ul><p>For example, suppose we have a <code>Product</code> table containing product information.</p><p>We can create a page object that allows users to:</p><ul><li>View products.</li><li>Open individual product records.</li><li>Create new products.</li><li>Modify existing products.</li></ul><p>A page object does not necessarily store data itself. Instead, it provides an interface for accessing and interacting with data stored in tables.</p><h2 id="declaring-a-page-object" tabindex="-1">Declaring a Page Object <a class="header-anchor" href="#declaring-a-page-object" aria-label="Permalink to “Declaring a Page Object”">​</a></h2><p>A page object is declared using the <code>page</code> keyword, followed by its object ID, name, and body.</p><p>Example:</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>page 50100 ProductList</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    PageType = List;</span></span>
<span class="line"><span>    SourceTable = Product;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    ApplicationArea = All;</span></span>
<span class="line"><span>    UsageCategory = Lists;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    layout</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        area(Content)</span></span>
<span class="line"><span>        {</span></span>
<span class="line"><span>            repeater(General)</span></span>
<span class="line"><span>            {</span></span>
<span class="line"><span>                field(&quot;No.&quot;; Rec.&quot;No.&quot;)</span></span>
<span class="line"><span>                {</span></span>
<span class="line"><span>                    ApplicationArea = All;</span></span>
<span class="line"><span>                }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>                field(Name; Rec.Name)</span></span>
<span class="line"><span>                {</span></span>
<span class="line"><span>                    ApplicationArea = All;</span></span>
<span class="line"><span>                }</span></span>
<span class="line"><span>            }</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Let&#39;s break down the declaration:</p><table tabindex="0"><thead><tr><th>Component</th><th>Description</th></tr></thead><tbody><tr><td><code>page</code></td><td>Declares a page object.</td></tr><tr><td><code>50100</code></td><td>The unique object ID within the relevant object ID range.</td></tr><tr><td><code>ProductList</code></td><td>The name of the page object.</td></tr><tr><td><code>{ }</code></td><td>Contains the page&#39;s properties, layout, triggers, and other definitions.</td></tr></tbody></table><p>Note: We&#39;ll cover <code>PageType</code>, <code>SourceTable</code>, <code>layout</code>, <code>area</code>, <code>repeater</code>, and <code>field</code> in their respective topics. For now, focus on understanding the overall page object structure.</p><h2 id="page-object-properties" tabindex="-1">Page Object Properties <a class="header-anchor" href="#page-object-properties" aria-label="Permalink to “Page Object Properties”">​</a></h2><p>Page objects have properties that determine their identity, behavior, and how they are presented or accessed within Business Central.</p><p>Some important properties include:</p><table tabindex="0"><thead><tr><th>Property</th><th>Description</th></tr></thead><tbody><tr><td><code>Caption</code></td><td>Specifies the user-facing title of the page.</td></tr><tr><td><code>PageType</code></td><td>Determines the type and general behavior of the page.</td></tr><tr><td><code>SourceTable</code></td><td>Specifies the table from which the page retrieves its records.</td></tr><tr><td><code>ApplicationArea</code></td><td>Controls the application areas in which the page or its elements are available.</td></tr><tr><td><code>UsageCategory</code></td><td>Determines how the page is categorized in Tell Me search.</td></tr><tr><td><code>Editable</code></td><td>Determines whether users can edit records through the page.</td></tr></tbody></table><p>Example:</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>page 50100 ProductList</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    Caption = &#39;Products&#39;;</span></span>
<span class="line"><span>    PageType = List;</span></span>
<span class="line"><span>    SourceTable = Product;</span></span>
<span class="line"><span>    ApplicationArea = All;</span></span>
<span class="line"><span>    UsageCategory = Lists;</span></span>
<span class="line"><span>    Editable = true;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>We&#39;ll explore these properties in more detail as we progress through the chapter.</p><h2 id="page-object-ids-and-naming" tabindex="-1">Page Object IDs and Naming <a class="header-anchor" href="#page-object-ids-and-naming" aria-label="Permalink to “Page Object IDs and Naming”">​</a></h2><p>Like other AL application objects, page objects require an ID and a name.</p><ul><li>Object ID: A unique numeric identifier for the page object within the application.</li><li>Object Name: An identifier used to reference the page in AL code.</li></ul><p>For example:</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>page 50100 ProductList</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    // Page definition</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Here:</p><ul><li><code>50100</code> is the page ID.</li><li><code>ProductList</code> is the page name.</li></ul><p>You can reference this page elsewhere in AL using its name or ID, depending on the context.</p><p>Important: Object IDs must not conflict with other objects in the same application scope. When developing extensions, use an assigned object ID range to avoid conflicts with other applications.</p><h2 id="where-do-page-objects-appear-in-business-central" tabindex="-1">Where Do Page Objects Appear in Business Central? <a class="header-anchor" href="#where-do-page-objects-appear-in-business-central" aria-label="Permalink to “Where Do Page Objects Appear in Business Central?”">​</a></h2><p>Page objects provide the user-facing experience in Business Central.</p><p>Depending on their configuration, they can appear in different places, including:</p><ul><li>Role Center: The user&#39;s starting workspace.</li><li>Lists: Pages displaying collections of records.</li><li>Cards: Pages displaying individual records and their details.</li><li>Documents: Pages used to work with business documents.</li><li>Dialogs: Pages used for specific interactions with users.</li></ul><p>We&#39;ll examine these page types separately in the next topic.</p><h2 id="key-takeaways" tabindex="-1">Key Takeaways <a class="header-anchor" href="#key-takeaways" aria-label="Permalink to “Key Takeaways”">​</a></h2><ul><li>A Page Object defines a user interface in Business Central.</li><li>Page objects allow users to interact with data stored in tables.</li><li>Every page object has an ID and a name.</li><li>Page objects contain properties, layout definitions, triggers, and other AL constructs.</li><li>The <code>page</code> keyword is used to declare a page object.</li><li>The <code>SourceTable</code> property associates a page with a table.</li></ul><h2 id="further-reading" tabindex="-1">Further Reading <a class="header-anchor" href="#further-reading" aria-label="Permalink to “Further Reading”">​</a></h2><ul><li><a href="https://learn.microsoft.com/en-us/dynamics365/business-central/dev-itpro/developer/devenv-page-object" target="_blank" rel="noreferrer">Microsoft Learn – Page Object</a></li><li><a href="https://learn.microsoft.com/en-us/dynamics365/business-central/dev-itpro/developer/properties/devenv-properties" target="_blank" rel="noreferrer">Microsoft Learn – Page Properties</a></li></ul>`,41)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};